begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(10);
insert into organizations(id,slug,name) values('00000000-0000-4000-8000-000000008001','launch-test','Launch Test');
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008002','launch@argus.test');
insert into argus_members(user_id,organization_id,role,display_name) values('00000000-0000-4000-8000-000000008002','00000000-0000-4000-8000-000000008001','analyst','Launch');
insert into cases(id,organization_id,kind,canonical_ref,display_query) values('00000000-0000-4000-8000-000000008003','00000000-0000-4000-8000-000000008001','token','robinhood:0x1111111111111111111111111111111111111111','Token');
insert into report_versions(id,organization_id,case_id,version,payload) values('00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008003',1,'{"chain":"robinhood","address":"0x1111111111111111111111111111111111111111"}');
select ok(not has_table_privilege('authenticated','public.deep_launch_runs','select'),'browser cannot directly read private research');
select ok(not has_function_privilege('authenticated','public.claim_deep_launch(uuid,uuid,uuid,text)','execute'),'browser cannot bypass admission');
select throws_ok($$select claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008099','robinhood-launch-v1')$$,'P0001','active investigator membership required','nonmember rejected');
select throws_ok($$select claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008099','00000000-0000-4000-8000-000000008002','robinhood-launch-v1')$$,'P0001','active Robinhood report required','other report scope rejected');
select ok(claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008002','robinhood-launch-v1') is not null,'first collector gets lease');
select is(claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008002','robinhood-launch-v1'),null::uuid,'duplicate collector denied');
update deep_launch_runs set started_at=now()-interval '3 minutes' where organization_id='00000000-0000-4000-8000-000000008001';
select ok(claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008002','robinhood-launch-v1') is not null,'abandoned lease can be retried');
select is((select count(*)::integer from deep_launch_runs where organization_id='00000000-0000-4000-8000-000000008001' and state='failed'),1,'abandoned attempt retained');
update deep_launch_runs set state='completed',finished_at=now(),result='{"fixture":true}' where organization_id='00000000-0000-4000-8000-000000008001' and state='running';
select is(claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008002','robinhood-launch-v1'),null::uuid,'saved result is reused');
update cases set status='archived' where id='00000000-0000-4000-8000-000000008003';
select throws_ok($$select claim_deep_launch('00000000-0000-4000-8000-000000008001','00000000-0000-4000-8000-000000008004','00000000-0000-4000-8000-000000008002','robinhood-launch-v1')$$,'P0001','active Robinhood report required','archived cases cannot start research');
select * from finish();
rollback;
